import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        N = int(next(iterator))
        S = next(iterator)

        stacks = []
        for _ in range(N):
            stacks.append(next(iterator))

        if S == "Dee":
            moves_dee = 0
            moves_dum = 0

            for stack in stacks:
                if not stack:
                    continue

                if stack[0] == '0':
                    idx = 0
                    while idx < len(stack) and stack[idx] == '0':
                        idx += 1
                    moves_dee += idx

                    if idx < len(stack):
                        if stack[idx] == '1':
                            k = 0
                            while idx + k < len(stack) and stack[idx + k] == '1':
                                k += 1
                            moves_dum += k
                else:
                    if stack[0] == '1':
                        k = 0
                        while k < len(stack) and stack[k] == '1':
                            k += 1
                        moves_dum += k

                        if k < len(stack):
                            if stack[k] == '0':
                                idx = 0
                                while k + idx < len(stack) and stack[k + idx] == '0':
                                    idx += 1
                                moves_dee += idx

            if moves_dee > 0:
                if moves_dee > moves_dum:
                    results.append("Dee")
                else:
                    results.append("Dum")
            else:
                results.append("Dum")
        else:
            moves_dee = 0
            moves_dum = 1

            for stack in stacks:
                if not stack:
                    if stack:
                        pass
                    else:
                        continue

                if stack[0] == '1':
                    k = 0
                    while k < len(stack) and stack[k] == '1':
                        k += 1
                    moves_dum += k

                    if k < len(stack):
                        if stack[k] == '0':
                            idx = 0
                            while k + idx < len(stack) and stack[k + idx] == '\n' or (k + idx < len(stack) and stack[k + idx] == '0'):
                                if k + idx >= len(stack):
                                    break
                                if stack[k + idx] == '0':
                                    idx += 1

                if stack[0] == '0':
                    idx = len(stack) - 1
                    while idx >= 0 and stack[idx] == '0':
                        idx -= 1
                    count = len(stack) - (idx + 1)
                    moves_dee += count

                    if idx >= 0:
                        if stack[idx] == '1':
                            k = 1
                            while idx - k >= 0 and stack[idx - k] == '1':
                                k += 1
                            moves_dee += k

            if moves_dum > moves_dee:
                results.append("Dum")
            else:
                results.append("Dee")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
